function relsOf(e) { return ORD.filter((o) => (o.a === e.id || o.b === e.id) && (CS.role === 'GM' || o.shared)).map((o) => { const other = EV.find((x) => x.id === (o.a === e.id ? o.b : o.a)); if (!other || !canSee(other)) return null; const t = o.kind === 'before' ? (o.a === e.id ? `Happened before “${other.name}”` : `Happened after “${other.name}”`) : (o.a === e.id ? `Caused “${other.name}”` : `Was caused by “${other.name}”`); return { id: o.id, text: t, shared: o.shared, o, other }; }).filter(Boolean); }
